function maxAdjacentDistance(nums) {
  const n = nums.length;
  let best = 0;

  for (let i = 0; i < n; i++) {
    const next = nums[(i + 1) % n];
    best = Math.max(best, Math.abs(nums[i] - next));
  }
  return best;
}

