function maxAdjacentDistance(nums) {
  // Line the array up against itself shifted by one place; the first element wraps to the end.
  const shifted = [...nums.slice(1), nums[0]];
  const gaps = nums.map((value, i) => Math.abs(value - shifted[i]));
  return Math.max(...gaps);
}

